CREATE POLICY "status_photos_insert_own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'status-photos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "status_photos_select_own" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'status-photos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "status_photos_update_own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'status-photos' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'status-photos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "status_photos_delete_own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'status-photos' AND (storage.foldername(name))[1] = auth.uid()::text);